package com.libertyrecomp;
import android.app.*;
import android.widget.*;
import java.io.*;
import java.util.*;
final class SessionResultsUi {
 static void show(Activity a,File data){try{SessionHistory.recoverBenchmark(data,a.getFilesDir());}catch(IOException ignored){}LinearLayout body=new LinearLayout(a);body.setOrientation(LinearLayout.VERTICAL);body.addView(ModernUi.text(a,"Publisher FPS measures game publications. Select two completed benchmarks to compare; differing conditions are listed.",12,ModernUi.MUTED));final List<Properties> selected=new ArrayList<>();Button compare=ModernUi.button(a,"Compare selected",false);compare.setEnabled(false);body.addView(compare);try{List<Properties> records=SessionHistory.records(data);for(Properties p:records){boolean benchmark="benchmark".equals(p.getProperty("kind"));String time=java.text.DateFormat.getDateTimeInstance().format(new Date((long)SessionHistory.number(p,"sampled",SessionHistory.number(p,"started",0))));String label=benchmark?String.format(Locale.ROOT,"%.2f FPS · p95 %.2f ms",SessionHistory.number(p,"benchmark.published_fps",0),SessionHistory.number(p,"benchmark.interval_p95_ms",0)):String.format(Locale.ROOT,"Last active %.1f FPS",SessionHistory.number(p,"fps",0));CheckBox row=new CheckBox(a);row.setText((benchmark?"BENCHMARK · ":"SESSION · ")+time+"\n"+label+"\n"+p.getProperty("gpu","GPU unknown")+" · "+p.getProperty("cache.phase","unspecified"));row.setTextColor(ModernUi.TEXT);row.setTextSize(12);row.setEnabled(benchmark);body.addView(row);row.setOnCheckedChangeListener((v,on)->{if(on){if(selected.size()==2){row.setChecked(false);return;}selected.add(p);}else selected.remove(p);compare.setEnabled(selected.size()==2);});Button details=ModernUi.button(a,"Details",false);body.addView(details);details.setOnClickListener(v->{TextView text=ModernUi.text(a,details(p),12,ModernUi.TEXT);text.setTextIsSelectable(true);ModernUi.dialog(a,"Recorded session",text).show();});}if(records.isEmpty())body.addView(ModernUi.text(a,"No recorded sessions yet.",13,ModernUi.MUTED));}catch(IOException error){body.addView(ModernUi.text(a,error.getMessage(),13,ModernUi.MUTED));}compare.setOnClickListener(v->{if(selected.size()!=2)return;Properties first=selected.get(0),second=selected.get(1);double x=SessionHistory.number(first,"benchmark.published_fps",0),y=SessionHistory.number(second,"benchmark.published_fps",0);String differences=SessionHistory.differences(first,second);String firstQuality=SessionHistory.comparisonQuality(first),secondQuality=SessionHistory.comparisonQuality(second);String quality=(firstQuality.isEmpty()?"":"First run: "+firstQuality+"\n")+(secondQuality.isEmpty()?"":"Second run: "+secondQuality+"\n");String text=String.format(Locale.ROOT,"First %.2f FPS → Second %.2f FPS\np95 %.2f ms → %.2f ms\n",x,y,SessionHistory.number(first,"benchmark.interval_p95_ms",0),SessionHistory.number(second,"benchmark.interval_p95_ms",0))+(x>0?String.format(Locale.ROOT,"Observed FPS difference %+.1f%%\n",(y/x-1)*100):"")+"Intervals over 50 ms: "+first.getProperty("benchmark.over_50ms","unknown")+" → "+second.getProperty("benchmark.over_50ms","unknown")+"\n\n"+quality+(differences.isEmpty()?"Recorded settings match. Route and starting temperatures still require a controlled test.":"Conditions differ:\n"+differences);ModernUi.dialog(a,"Benchmark comparison",ModernUi.text(a,text,13,ModernUi.TEXT)).show();});ModernUi.dialog(a,"Sessions & benchmarks",body).show();}
 static String details(Properties p){StringBuilder text=new StringBuilder();for(String k:new TreeSet<>(p.stringPropertyNames()))text.append(k).append(": ").append(p.getProperty(k)).append('\n');return text.toString();}
 private SessionResultsUi(){}
}
